'use client';import {useState} from 'react';import {UserRound,Search} from 'lucide-react';import {money} from '@/lib/data';import {useStore} from '@/lib/store';import {Panel,Toolbar} from '@/components/Panel';export default function Customers(){const{customers,bills}=useStore();const[q,setQ]=useState('');const data=customers.filter(c=>(c.name+' '+c.mobile+' '+c.place).toLowerCase().includes(q.toLowerCase()));return <><Toolbar title="Customers" subtitle="Customer credit balances are linked by mobile number"/><Panel><div className="filterbar"><div className="search-box dark"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search customer..."/></div></div><div className="customer-grid">{data.map(c=><div className="customer-card" key={c.id}><div className="customer-avatar"><UserRound/></div><div><h3>{c.name}</h3><span>{c.mobile}</span><small>{c.place}</small></div><div className={c.balance?'customer-balance due':'customer-balance'}><span>Credit Balance</span><b>{money(c.balance)}</b></div><div className="customer-stat"><span>Total Bills</span><b>{bills.filter(b=>b.customer.mobile===c.mobile).length}</b></div></div>)}</div></Panel></>}
